let stop = Arc::new(AtomicBool::new(false));
let flag = Arc::clone(&stop);
let (tx, rx) = mpsc::channel::<Job>();

let worker = thread::spawn(move || {
    while !flag.load(Ordering::Acquire) {        // safe point
        if let Ok(job) = rx.recv_timeout(Duration::from_millis(100)) { run(job); }
    }
    flush_and_release();                         // phase 2 cleanup
});

stop.store(true, Ordering::Release);             // phase 1: request
worker.join().unwrap();                          // phase 2: completion

